const raw = $input.first().json;
const docs = Array.isArray(raw.data) ? raw.data : $input.all().map(item => item.json);
const results = [];
const now = Date.now();
const thirtyDaysMs = 30 * 24 * 60 * 60 * 1000;
const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;

for (const doc of docs) {
  if (!doc || !doc._id) continue;
  let needsIncident = false;
  let needsGmailAlert = false;
  const issues = [];
  let severity = 'low';

  if (doc.integrityStatus === 'tampered' || doc.integrityStatus === 'missing') {
    needsIncident = true;
    needsGmailAlert = true;
    severity = 'critical';
    issues.push(`Xâm phạm toàn vẹn tệp: ${doc.integrityStatus}`);
  }

  if (doc.healthScore < 50) {
    needsIncident = true;
    needsGmailAlert = true;
    severity = 'critical';
    issues.push(`Điểm sức khỏe nguy hiểm: ${doc.healthScore}/100`);
  } else if (doc.healthScore < 80) {
    issues.push(`Điểm sức khỏe cảnh báo: ${doc.healthScore}/100`);
  }

  if (doc.expiresAt) {
    const exp = new Date(doc.expiresAt).getTime();
    if (exp < now) {
      needsIncident = true;
      needsGmailAlert = true;
      severity = severity === 'critical' ? 'critical' : 'high';
      issues.push('Tài liệu đã quá hạn hiệu lực');
    } else if (exp - now <= sevenDaysMs) {
      needsGmailAlert = true;
      severity = severity === 'critical' ? 'critical' : 'high';
      issues.push('Cảnh báo khẩn: Tài liệu sắp hết hạn trong <= 7 ngày');
    } else if (exp - now <= thirtyDaysMs) {
      needsGmailAlert = true;
      issues.push('Nhắc nhở: Tài liệu sắp hết hạn trong 30 ngày');
    }
  }

  results.push({
    json: {
      documentId: doc._id,
      title: doc.title,
      ownerEmail: doc.ownerEmail || '',
      healthScore: doc.healthScore,
      healthStatus: doc.healthStatus,
      integrityStatus: doc.integrityStatus,
      needsIncident,
      needsGmailAlert,
      severity,
      issues,
      issuesSummary: issues.join('; ')
    }
  });
}

return results.length ? results : [{ json: { needsIncident: false, needsGmailAlert: false, total: 0 } }];

